<?php require_once __DIR__.'/../includes/auth.php'; $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=$pdo->prepare('SELECT * FROM categories WHERE id=?');$s->execute([$id]);$row=$s->fetch();if(!$row){flash('error','Category not found.');redirect('index.php');}$pageTitle='Edit category';$base='/shop-inventory-management';$name=$row['name'];$description=$row['description']??'';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$description=trim($_POST['description']??'');if($name==='')$error='Category name is required.';else{try{$s=$pdo->prepare('UPDATE categories SET name=?,description=? WHERE id=?');$s->execute([$name,$description?:null,$id]);flash('success','Category updated.');redirect('index.php');}catch(PDOException $e){$error=$e->getCode()==='23000'?'That category name already exists.':'Could not update category.';}}}require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/sidebar.php';?>
<div class="page-heading"><div><h1>Edit category</h1><p>Update category information.</p></div><a class="btn" href="index.php">← Back</a></div><div class="panel form-panel"><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Category name *<input name="name" required maxlength="100" value="<?=e($name)?>"></label><label>Description<textarea name="description" rows="4"><?=e($description)?></textarea></label><div class="form-actions"><button class="btn primary">Update category</button><a class="btn" href="index.php">Cancel</a></div></form></div><?php require __DIR__.'/../includes/footer.php';?>
